var addSorting = (function() {
    'use strict';
    var cols,
        currentSort = {
            index: 0,
            desc: false
        };

    // returns the summary table element
    function getTable() {
        return document.querySelector('.coverage-summary');
    }
    // returns the thead element of the summary table
    function getTableHeader() {
        return getTable().querySelector('thead tr');
    }
    // returns the tbody element of the summary table
    function getTableBody() {
        return getTable().querySelector('tbody');
    }
    // returns the th element for nth column
    function getNthColumn(n) {
        return getTableHeader().querySelectorAll('th')[n];
    }

    function onFilterInput() {
        const searchValue = document.getElementById('fileSearch').value;
        const rows = document.getElementsByTagName('tbody')[0].children;

        // Try to create a RegExp from the searchValue. If it fails (invalid regex),
        // it will be treated as a plain text search
        let searchRegex;
        try {
            searchRegex = new RegExp(searchValue, 'i'); // 'i' for case-insensitive
        } catch (error) {
            searchRegex = null;
        }

        for (let i = 0; i < rows.length; i++) {
            const row = rows[i];
            let isMatch = false;

            if (searchRegex) {
                // If a valid regex was created, use it for matching
                isMatch = searchRegex.test(row.textContent);
            } else {
                // Otherwise, fall back to the original plain text search
                isMatch = row.textContent
                    .toLowerCase()
                    .includes(searchValue.toLowerCase());
            }

            row.style.display = isMatch ? '' : 'none';
        }
    }

    // loads the search box
    function addSearchBox() {
        var template = document.getElementById('filterTemplate');
        var templateClone = template.content.cloneNode(true);
        templateClone.getElementById('fileSearch').oninput = onFilterInput;
        template.parentElement.appendChild(templateClone);
    }

    // loads all columns
    function loadColumns() {
        var colNodes = getTableHeader().querySelectorAll('th'),
            colNode,
            cols = [],
            col,
            i;

        for (i = 0; i < colNodes.length; i += 1) {
            colNode = colNodes[i];
            col = {
                key: colNode.getAttribute('data-col'),
                sortable: !colNode.getAttribute('data-nosort'),
                type: colNode.getAttribute('data-type') || 'string'
            };
            cols.push(col);
            if (col.sortable) {
                col.defaultDescSort = col.type === 'number';
                colNode.innerHTML =
                    colNode.innerHTML + '<span class="sorter"></span>';
            }
        }
        return cols;
    }
    // attaches a data attribute to every tr element with an object
    // of data values keyed by column name
    function loadRowData(tableRow) {
        var tableCols = tableRow.querySelectorAll('td'),
            colNode,
            col,
            data = {},
            i,
            val;
        for (i = 0; i < tableCols.length; i += 1) {
            colNode = tableCols[i];
            col = cols[i];
            val = colNode.getAttribute('data-value');
            if (col.type === 'number') {
                val = Number(val);
            }
            data[col.key] = val;
        }
        return data;
    }
    // loads all row data
    function loadData() {
        var rows = getTableBody().querySelectorAll('tr'),
            i;

        for (i = 0; i < rows.length; i += 1) {
            rows[i].data = loadRowData(rows[i]);
        }
    }
    // sorts the table using the data for the ith column
    function sortByIndex(index, desc) {
        var key = cols[index].key,
            sorter = function(a, b) {
                a = a.data[key];
                b = b.data[key];
                return a < b ? -1 : a > b ? 1 : 0;
            },
            finalSorter = sorter,
            tableBody = document.querySelector('.coverage-summary tbody'),
            rowNodes = tableBody.querySelectorAll('tr'),
            rows = [],
            i;

        if (desc) {
            finalSorter = function(a, b) {
                return -1 * sorter(a, b);
            };
        }

        for (i = 0; i < rowNodes.length; i += 1) {
            rows.push(rowNodes[i]);
            tableBody.removeChild(rowNodes[i]);
        }

        rows.sort(finalSorter);

        for (i = 0; i < rows.length; i += 1) {
            tableBody.appendChild(rows[i]);
        }
    }
    // removes sort indicators for current column being sorted
    function removeSortIndicators() {
        var col = getNthColumn(currentSort.index),
            cls = col.className;

        cls = cls.replace(/ sorted$/, '').replace(/ sorted-desc$/, '');
        col.className = cls;
    }
    // adds sort indicators for current column being sorted
    function addSortIndicators() {
        getNthColumn(currentSort.index).className += currentSort.desc
            ? ' sorted-desc'
            : ' sorted';
    }
    // adds event listeners for all sorter widgets
    function enableUI() {
        var i,
            el,
            ithSorter = function ithSorter(i) {
                var col = cols[i];

                return function() {
                    var desc = col.defaultDescSort;

                    if (currentSort.index === i) {
                        desc = !currentSort.desc;
                    }
                    sortByIndex(i, desc);
                    removeSortIndicators();
                    currentSort.index = i;
                    currentSort.desc = desc;
                    addSortIndicators();
                };
            };
        for (i = 0; i < cols.length; i += 1) {
            if (cols[i].sortable) {
                // add the click event handler on the th so users
                // dont have to click on those tiny arrows
                el = getNthColumn(i).querySelector('.sorter').parentElement;
                if (el.addEventListener) {
                    el.addEventListener('click', ithSorter(i));
                } else {
                    el.attachEvent('onclick', ithSorter(i));
                }
            }
        }
    }
    // adds sorting functionality to the UI
    return function() {
        if (!getTable()) {
            return;
        }
        cols = loadColumns();
        loadData();
        addSearchBox();
        addSortIndicators();
        enableUI();
    };
})();

window.addEventListener('load', addSorting);

import { onCall, HttpsError } from "firebase-functions/v2/https";
import fetch from "node-fetch";

// We'll read the secret from environment variables
// In production, you would set this via Firebase CLI:
// firebase functions:secrets:set OPENROUTER_API_KEY
const OPENROUTER_API_KEY = process.env.OPENROUTER_API_KEY || "YOUR_OPENROUTER_KEY_HERE";

export const generateAIResponse = onCall(
  {
    cors: true,
    secrets: ["OPENROUTER_API_KEY"],
  },
  async (request) => {
    // 1. Ensure user is authenticated
    if (!request.auth) {
      throw new HttpsError(
        "unauthenticated",
        "Қолданушы жүйеге кірмеген. (Unauthenticated)"
      );
    }

    const apiKey = process.env.OPENROUTER_API_KEY || OPENROUTER_API_KEY;

    if (!apiKey || apiKey === "YOUR_OPENROUTER_KEY_HERE") {
      throw new HttpsError(
        "failed-precondition",
        "OpenRouter API кілті серверде бапталмаған."
      );
    }

    const { body } = request.data;

    if (!body || !body.messages) {
      throw new HttpsError(
        "invalid-argument",
        "Сұрау форматы қате. (Invalid request body)"
      );
    }

    try {
      const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${apiKey}`,
          "HTTP-Referer": "https://natije-ai.web.app",
          "X-Title": "Natije AI",
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
      });

      if (!response.ok) {
        const errorText = await response.text();
        console.error("OpenRouter error:", response.status, errorText);
        throw new HttpsError(
          "internal",
          `AI сервері қате қайтарды (${response.status})`
        );
      }

      const data = await response.json();
      return data;
    } catch (error: any) {
      console.error("Function Error:", error);
      throw new HttpsError("internal", error.message || "AI сұрауын орындау мүмкін болмады.");
    }
  }
);

import { useState } from 'react';
import { Bot, X, Send, User } from 'lucide-react';
import type { ChatMessage } from '../../types';
import { getChatResponse } from '../../services/ai';
import './ChatPanel.css';

interface ChatPanelProps {
  title?: string;
  messages: ChatMessage[];
  suggestions?: string[];
  onClose?: () => void;
  className?: string;
}

const renderFormattedMessage = (content: string) => {
  if (!content) return null;
  const lines = content.split('\n');
  return lines.map((line, index) => {
    const formatBold = (text: string) => {
      const parts = text.split(/\*\*(.*?)\*\*/g);
      return parts.map((part, partIdx) => {
        if (partIdx % 2 === 1) {
          return <strong key={partIdx} style={{ fontWeight: '600', color: 'var(--text-primary)' }}>{part}</strong>;
        }
        return part;
      });
    };

    const numberedMatch = /^\s*(\d+)[.)]\s+(.*)/.exec(line);
    if (numberedMatch) {
      const num = numberedMatch[1];
      const text = numberedMatch[2];
      return (
        <div key={index} className="chat-line-list-item chat-line-numbered" style={{ display: 'flex', gap: '6px', marginBottom: '6px', paddingLeft: '4px' }}>
          <span className="chat-list-number" style={{ fontWeight: '600', color: 'var(--accent-primary)', flexShrink: 0 }}>{num}.</span>
          <span style={{ flex: 1 }}>{formatBold(text)}</span>
        </div>
      );
    }

    const bulletMatch = /^\s*[-*•]\s+(.*)/.exec(line);
    if (bulletMatch) {
      const text = bulletMatch[1];
      return (
        <div key={index} className="chat-line-list-item chat-line-bullet" style={{ display: 'flex', gap: '8px', marginBottom: '6px', paddingLeft: '4px' }}>
          <span className="chat-list-bullet" style={{ color: 'var(--accent-primary)', flexShrink: 0 }}>•</span>
          <span style={{ flex: 1 }}>{formatBold(text)}</span>
        </div>
      );
    }

    if (line.trim() === '') {
      return <div key={index} className="chat-line-empty" style={{ height: '8px' }} />;
    }

    return (
      <div key={index} className="chat-line-text" style={{ marginBottom: '4px' }}>
        {formatBold(line)}
      </div>
    );
  });
};

export default function ChatPanel({
  title = 'AI көмекші',
  messages: initialMessages,
  suggestions = [],
  onClose,
  className = '',
}: ChatPanelProps) {
  const [messages, setMessages] = useState(initialMessages);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSend = async (messageToSend?: string) => {
    const text = (messageToSend || input).trim();
    if (!text || loading) return;

    const newMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      timestamp: new Date().toLocaleTimeString('kk-KZ', { hour: '2-digit', minute: '2-digit' }),
    };

    const updatedMessages = [...messages, newMsg];
    setMessages(updatedMessages);
    if (!messageToSend) setInput('');
    setLoading(true);

    try {
      const reply = await getChatResponse(text, messages);
      const botMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: reply,
        timestamp: new Date().toLocaleTimeString('kk-KZ', { hour: '2-digit', minute: '2-digit' }),
      };
      setMessages([...updatedMessages, botMsg]);
    } catch (err) {
      console.error("Failed to fetch chat reply:", err);
      const errorMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: 'Кешіріңіз, қате пайда болды. Сұрағыңызды қайта жазып көріңіз.',
        timestamp: new Date().toLocaleTimeString('kk-KZ', { hour: '2-digit', minute: '2-digit' }),
      };
      setMessages([...updatedMessages, errorMsg]);
    } finally {
      setLoading(false);
    }
  };

  const handleSuggestionClick = (suggestion: string) => {
    handleSend(suggestion);
  };

  return (
    <div className={`chat-panel ${className}`}>
      {/* Header */}
      <div className="chat-header">
        <div className="chat-header-title">
          <div className="chat-header-icon">
            <Bot size={16} />
          </div>
          {title}
        </div>
        {onClose && (
          <button className="chat-close-btn" onClick={onClose}>
            <X size={16} />
          </button>
        )}
      </div>

      {/* Suggestions */}
      {suggestions.length > 0 && (
        <div className="chat-suggestions">
          {suggestions.map((sug, idx) => (
            <button
              key={idx}
              className="chat-suggestion-btn"
              onClick={() => handleSuggestionClick(sug)}
            >
              {sug}
            </button>
          ))}
        </div>
      )}

      {/* Messages */}
      <div className="chat-messages">
        {messages.map((msg) => (
          <div key={msg.id} className={`chat-message chat-message-${msg.role === 'user' ? 'user' : 'bot'}`}>
            <div className="chat-message-avatar">
              {msg.role === 'user' ? <User size={14} /> : <Bot size={14} />}
            </div>
            <div>
              <div className="chat-message-name">
                {msg.role === 'user' ? 'Сен' : 'AI көмекші'}
                <span className="chat-message-time">{msg.timestamp}</span>
              </div>
              <div className="chat-message-content">
                {renderFormattedMessage(msg.content)}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Input */}
      <div className="chat-input-container">
        <div className="chat-input-wrapper">
          <input
            className="chat-input"
            type="text"
            placeholder={loading ? "AI жауап дайындап жатыр..." : "Сұрағыңызды жазыңыз..."}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            disabled={loading}
          />
          <button className="chat-send-btn" onClick={() => handleSend()} disabled={loading} style={{ opacity: loading ? 0.7 : 1 }}>
            {loading ? (
              <div className="spin" style={{ width: '14px', height: '14px', border: '2px solid white', borderTopColor: 'transparent', borderRadius: '50%' }} />
            ) : (
              <Send size={16} />
            )}
          </button>
        </div>
      </div>

      <p className="chat-disclaimer">
        AI жауаптары ұсыныс ретінде берілді, мұғалімнің шешімімен бекітіледі.
      </p>
    </div>
  );
}

import { useLocation, Link, useNavigate } from 'react-router-dom';
import {
  Home, FileText, MessageCircle, Calendar, TrendingUp,
  BookOpen, Award, Lightbulb, Folder, PlusCircle,
  Upload, HelpCircle, Bot, Users, CheckCircle,
