// @ts-nocheck
import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import {
  Archive, FileText, Bot, Loader
} from 'lucide-react';
import MainLayout from '../../components/layout/MainLayout';
import Badge, { StatusBadge } from '../../components/ui/Badge';
import { useAuth } from '../../contexts/AuthContext';
import type { Submission } from '../../types';
import { db } from '../../lib/firebase';
import { collection, query, where, onSnapshot } from 'firebase/firestore';
import { STATUS_MAP, ASSIGNMENT_TYPES } from '../../lib/constants';
import { formatDate } from '../../lib/utils';
import './ArchivePage.css';

export default function ArchivePage() {
  const { user } = useAuth();
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(true);
  const [studentDocIds, setStudentDocIds] = useState<string[]>([]);

  useEffect(() => {
    if (!db || !user) return;

    const studentQuery = query(
      collection(db, 'students'), 
      where("email", "==", user.email)
    );

    const unsubscribe = onSnapshot(studentQuery, (querySnapshot) => {
      const ids = [user.id];
      querySnapshot.forEach((docSnap) => {
        ids.push(docSnap.id);
      });
      setStudentDocIds(Array.from(new Set(ids)));
    });

    return () => unsubscribe();
  }, [user]);

  useEffect(() => {
    if (!db || !user || studentDocIds.length === 0) return;

    setLoading(true);
    const q = query(collection(db, 'submissions'), where("studentId", "in", studentDocIds));

    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const submissionsData: Submission[] = [];
      querySnapshot.forEach((docSnap) => {
        submissionsData.push({ id: docSnap.id, ...docSnap.data() } as Submission);
      });
      // Sort newest first
      submissionsData.sort((a, b) => {
        const timeA = (a.createdAt as any)?.seconds || 0;
        const timeB = (b.createdAt as any)?.seconds || 0;
        return timeB - timeA;
      });
      setSubmissions(submissionsData);
      setLoading(false);
    }, (error) => {
      console.error("Failed to sync student submissions", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [studentDocIds, user]);

  return (
    <MainLayout
      breadcrumbs={[
        { label: 'Менің тапсырмаларым', path: '/assignments' },
      ]}
    >
      <div className="archive-page">
        {/* Header */}
        <div className="archive-header">
          <h1 className="archive-title">
            <Archive size={24} /> Менің жұмыстарым
          </h1>
          <p className="archive-description">
            Мұғалім жүктеген барлық жұмыстарыңыз бен AI бағалау нәтижелері осында сақталады.
          </p>
        </div>

        {/* Grid: Table + Sidebar */}
        <div className="archive-grid">
          {/* Table */}
          <div className="archive-table-wrapper">
            {loading ? (
              <div style={{ display: 'flex', justifyContent: 'center', padding: 'var(--space-8)' }}>
                <Loader className="spin" size={32} />
              </div>
            ) : (
              <>
                <table className="archive-table">
                  <thead>
                    <tr>
                      <th>Тапсырма атауы</th>
                      <th>Пән</th>
                      <th>Күні</th>
                      <th>Статус</th>
                      <th>Түрі</th>
                      <th>Әрекет</th>
                    </tr>
                  </thead>
                  <tbody>
                    {submissions.length > 0 ? submissions.map((sub) => (
                      <tr key={sub.id}>
                        <td>
                          <div className="archive-table-title">
                            <div className={`archive-table-icon archive-table-icon-${ASSIGNMENT_TYPES[sub.type]?.color || 'gray'}`}>
                              <FileText size={16} />
                            </div>
                            <div className="archive-table-name">
                              <h4>{sub.title}</h4>
                            </div>
                          </div>
                        </td>
                        <td>{sub.subject}</td>
                        <td>{formatDate(sub.createdAt)}</td>
                        <td>
                          <StatusBadge 
                            status={sub.status === 'error' ? 'error' : sub.status === 'reviewed' ? 'success' : sub.status === 'pending_teacher_review' ? 'warning' : 'info'} 
                            label={STATUS_MAP[sub.status]?.label || sub.status} 
                          />
                        </td>
                        <td>
                          <Badge color={ASSIGNMENT_TYPES[sub.type]?.color as any || 'gray'} filled>
                            {ASSIGNMENT_TYPES[sub.type]?.label || sub.type}
                          </Badge>
                        </td>
                        <td>
                          <Link to={`/assignments/${sub.id}`} className="archive-action-btn" style={{ textDecoration: 'none' }}>
                            Ашу
                          </Link>
                        </td>
                      </tr>
                    )) : (
                      <tr>
                        <td colSpan={6} style={{ textAlign: 'center', padding: 'var(--space-6)', color: 'var(--text-tertiary)' }}>
                          Жүктелген тапсырмалар әлі жоқ.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </>
            )}
          </div>

          {/* Right Sidebar */}
          <div className="archive-sidebar">
            {/* AI Widget */}
            <div className="archive-ai-widget">
              <h3 className="archive-sidebar-title">AI көмекші</h3>
              <div className="archive-ai-icon">
                <Bot size={28} />
              </div>
              <p className="archive-ai-text">
                Жұмыстарыңыздың нәтижесін талдап, сізге қателермен жұмыс істеуге көмектесемін!
              </p>
            </div>
          </div>
        </div>
      </div>
    </MainLayout>
  );
}

import { useState } from 'react';
import { KeyRound, Loader, CheckCircle } from 'lucide-react';
import MainLayout from '../../components/layout/MainLayout';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import { useAuth } from '../../contexts/AuthContext';
import { useToast } from '../../contexts/ToastContext';
import { findClassByInviteCode } from '../../services/classes';
import { addStudent } from '../../services/students';

export default function JoinClassPage() {
  const { user } = useAuth();
  const toast = useToast();
  const [code, setCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [joinedClass, setJoinedClass] = useState<string | null>(null);

  const handleJoin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!code.trim() || !user) return;

    try {
      setLoading(true);
      const found = await findClassByInviteCode(code.trim());
      
      if (!found) {
        toast.error('Бұл код бойынша сынып табылмады. Кодты тексеріңіз.');
        return;
      }

      // Add student to the class
      const result = await addStudent(found.id, user.name, user.email, user.id);
      
      setJoinedClass(found.name);
      if (result.alreadyExisted) {
        toast.info(`Сіз бұл сыныпқа бұрыннан қосылғансыз.`);
      } else {
        toast.success(`"${found.name}" сыныбына сәтті қосылдыңыз!`);
      }
      setCode('');
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Сыныпқа қосылу кезінде қате пайда болды.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <MainLayout breadcrumbs={[{ label: 'Сыныпқа қосылу' }]}>
      <div style={{ maxWidth: '480px', margin: '0 auto', paddingTop: '40px' }}>
        <div style={{ textAlign: 'center', marginBottom: '32px' }}>
          <div style={{ width: '64px', height: '64px', borderRadius: '50%', background: 'var(--accent-primary-light)', color: 'var(--accent-primary)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 16px' }}>
            <KeyRound size={28} />
          </div>
          <h1 style={{ fontSize: '1.5rem', fontWeight: 700, marginBottom: '8px' }}>Сыныпқа қосылу</h1>
          <p style={{ color: 'var(--text-secondary)', fontSize: '0.9375rem' }}>
            Мұғалімнен алған 6-таңбалы кодты енгізіңіз
          </p>
        </div>

        {joinedClass ? (
          <Card padding="xl" style={{ textAlign: 'center' }}>
            <CheckCircle size={48} style={{ color: 'var(--color-success)', marginBottom: '16px' }} />
            <h2 style={{ fontSize: '1.125rem', fontWeight: 600, marginBottom: '8px' }}>Сәтті қосылдыңыз!</h2>
            <p style={{ color: 'var(--text-secondary)' }}>Сынып: <strong>{joinedClass}</strong></p>
            <Button variant="ghost" size="sm" style={{ marginTop: '16px' }} onClick={() => setJoinedClass(null)}>
              Тағы бір сыныпқа қосылу
            </Button>
          </Card>
        ) : (
          <Card padding="xl">
            <form onSubmit={handleJoin} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
              <div>
                <label style={{ display: 'block', marginBottom: '8px', fontWeight: 500 }}>Сынып коды</label>
                <input
                  className="form-input"
                  type="text"
                  placeholder="мысалы: A3K7M2"
                  value={code}
                  onChange={(e) => setCode(e.target.value.toUpperCase())}
                  maxLength={6}
                  style={{ fontSize: '1.25rem', textAlign: 'center', letterSpacing: '4px', fontWeight: 600 }}
                  required
                />
              </div>
              <Button type="submit" variant="primary" size="lg" fullWidth disabled={loading || code.length < 6}>
                {loading ? <Loader size={18} className="spin" /> : 'Қосылу'}
              </Button>
            </form>
          </Card>
        )}
      </div>
    </MainLayout>
  );
}

// @ts-nocheck
import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Archive, FileText, Award, Search, Bot, Star, Loader } from 'lucide-react';
import MainLayout from '../../components/layout/MainLayout';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import Badge from '../../components/ui/Badge';
import { useAuth } from '../../contexts/AuthContext';
import { collection, query, where, onSnapshot } from 'firebase/firestore';
import type { Submission } from '../../types';
import { formatDate } from '../../lib/utils';
import { ASSIGNMENT_TYPES } from '../../lib/constants';
import './StudentArchivePage.css';

export default function StudentArchivePage() {
  const { user } = useAuth();
  
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [studentDocIds, setStudentDocIds] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedSubjectFilter, setSelectedSubjectFilter] = useState('all');

  // 1. Resolve student document IDs
  useEffect(() => {
    if (!db || !user) return;

    const studentQuery = query(
      collection(db, 'students'), 
      where("email", "==", user.email)
    );

    const unsubscribe = onSnapshot(studentQuery, (querySnapshot) => {
      const ids = [user.id];
      querySnapshot.forEach((docSnap) => {
        ids.push(docSnap.id);
      });
      setStudentDocIds(Array.from(new Set(ids)));
    });

    return () => unsubscribe();
  }, [user]);

  // 2. Listen to reviewed submissions only
  useEffect(() => {
    if (!db || !user || studentDocIds.length === 0) return;

    setLoading(true);
    const q = query(
      collection(db, 'submissions'), 
      where("studentId", "in", studentDocIds),
      where("status", "==", "reviewed")
    );

    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const submissionsData: Submission[] = [];
      querySnapshot.forEach((docSnap) => {
        submissionsData.push({ id: docSnap.id, ...docSnap.data() } as Submission);
      });
      // Sort newest first
      submissionsData.sort((a, b) => {
        const timeA = (a.createdAt as any)?.seconds || 0;
        const timeB = (b.createdAt as any)?.seconds || 0;
        return timeB - timeA;
      });
      setSubmissions(submissionsData);
      setLoading(false);
    }, (error) => {
      console.error("Failed to sync student archive submissions", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [studentDocIds, user]);

  // Calculations
  const maxScore = submissions.length > 0 ? Math.max(...submissions.map(s => s.score || 0)) : 0;
  const averageScore = submissions.length > 0 
    ? Math.round(submissions.reduce((sum, s) => sum + (s.score || 0), 0) / submissions.length)
    : 0;

  // Extract unique subjects for filter
  const subjects = Array.from(new Set(submissions.map(s => s.subject)));

  // Filter archived submissions
  const filteredSubmissions = submissions.filter(sub => {
    const matchesSearch = sub.title.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesSubject = selectedSubjectFilter === 'all' || sub.subject === selectedSubjectFilter;
    return matchesSearch && matchesSubject;
  });

  const getTypeBadgeColor = (type: string) => {
    switch (type) {
      case 'assignment': return 'blue';
      case 'test': return 'red';
      case 'project': return 'purple';
      case 'essay': return 'yellow';
      default: return 'gray';
    }
  };

  const formatType = (type: string) => {
    return ASSIGNMENT_TYPES[type] || type;
  };

  return (
    <MainLayout
      breadcrumbs={[
        { label: 'Басты бет', path: '/' },
        { label: 'Архив' },
      ]}
    >
      {/* Header */}
      <div className="archive-page-welcome">
        <div>
          <h1 className="archive-page-title">
            <Archive size={28} style={{ marginRight: '8px', color: 'var(--accent-primary)', verticalAlign: 'middle' }} />
            Жұмыстар архиві
          </h1>
          <p className="archive-page-subtitle">Бағаланған және тексерілген жұмыстарыңыздың толық тарихы мен портфолиосы.</p>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="archive-stats-row">
        <Card className="archive-stat-card">
          <div className="stat-icon-wrapper" style={{ background: 'var(--accent-primary-light)', color: 'var(--accent-primary)' }}>
            <FileText size={20} />
          </div>
          <div className="stat-info">
            <span className="stat-label">Бағаланған жұмыстар</span>
            <span className="stat-value">{submissions.length}</span>
          </div>
        </Card>

        <Card className="archive-stat-card">
          <div className="stat-icon-wrapper" style={{ background: 'var(--color-success-light)', color: 'var(--color-success)' }}>
            <Award size={20} />
          </div>
          <div className="stat-info">
            <span className="stat-label">Ең жоғары балл</span>
            <span className="stat-value">{submissions.length > 0 ? `${maxScore}/100` : '—'}</span>
          </div>
        </Card>

        <Card className="archive-stat-card">
          <div className="stat-icon-wrapper" style={{ background: 'rgba(59, 130, 246, 0.1)', color: '#3b82f6' }}>
            <Star size={20} />
          </div>
          <div className="stat-info">
            <span className="stat-label">Орташа үлгерім</span>
            <span className="stat-value">{submissions.length > 0 ? `${averageScore}%` : '—'}</span>
          </div>
        </Card>
      </div>

      {/* Filters Card */}
      <Card style={{ marginBottom: '24px' }}>
        <div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap' }}>
          {/* Search */}
          <div style={{ flex: 1, minWidth: '240px', position: 'relative' }}>
            <Search size={18} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-tertiary)' }} />
            <input
              type="text"
              placeholder="Тапсырма атауын іздеу..."
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="form-input"
              style={{ width: '100%', paddingLeft: '38px' }}
            />
          </div>

          {/* Subject Filter */}
          <div style={{ width: '200px' }}>
            <select
              value={selectedSubjectFilter}
              onChange={e => setSelectedSubjectFilter(e.target.value)}
              className="form-input"
              style={{ width: '100%' }}
            >
              <option value="all">Барлық пәндер</option>
              {subjects.map((sub, idx) => (
                <option key={idx} value={sub}>{sub}</option>
              ))}
            </select>
          </div>
        </div>
      </Card>

      {/* Main Grid */}
      <div className="archive-page-grid">
        {/* Table Column */}
        <div className="archive-main-column">
          <Card>
            {loading ? (
              <div style={{ display: 'flex', justifyContent: 'center', padding: 'var(--space-8)' }}>
                <Loader className="spin" />
              </div>
            ) : filteredSubmissions.length > 0 ? (
              <div style={{ overflowX: 'auto' }}>
                <table className="archive-table-style">
                  <thead>
                    <tr>
                      <th>Тапсырма атауы</th>
                      <th>Пән</th>
                      <th>Күні</th>
                      <th>Түрі</th>
                      <th>Баға (Балл)</th>
                      <th>Әрекет</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredSubmissions.map((sub) => (
                      <tr key={sub.id}>
                        <td>
                          <div style={{ fontWeight: 500 }}>{sub.title}</div>
                          <div style={{ fontSize: '0.75rem', color: 'var(--text-secondary)' }}>Файл: {sub.fileName}</div>
                        </td>
                        <td>{sub.subject}</td>
                        <td style={{ fontSize: '0.875rem', color: 'var(--text-secondary)' }}>
                          {formatDate(sub.createdAt)}
                        </td>
                        <td>
                          <Badge color={getTypeBadgeColor(sub.type) as any} filled>
                            {formatType(sub.type)}
                          </Badge>
                        </td>
                        <td>
                          <span className="archive-score-badge">
                            {sub.score || 0}/100
                          </span>
                        </td>
                        <td>
                          <Link to={`/assignments/${sub.id}`} style={{ textDecoration: 'none' }}>
                            <Button variant="ghost" size="sm">
                              Талдауды ашу
                            </Button>
                          </Link>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div style={{ padding: 'var(--space-8)', textAlign: 'center', color: 'var(--text-tertiary)' }}>
                <FileText size={40} style={{ margin: '0 auto var(--space-3)' }} />
                <p>Архивте жұмыстар табылмады.</p>
              </div>
            )}
          </Card>
        </div>

        {/* Sidebar Column: AI Insights */}
        <div className="archive-sidebar-column">
          <Card className="ai-insights-card">
            <h3 className="sidebar-title">
              <Bot size={18} style={{ color: 'var(--accent-primary)', marginRight: '8px', verticalAlign: 'middle' }} />
              AI Ұсыныстар
            </h3>
            <div className="ai-insights-content">
              {submissions.length > 0 ? (
                <>
                  <p className="ai-insight-text">
                    Соңғы архивтелген жұмыстарыңыздың нәтижелерін ескере отырып, мына тақырыптарға назар аудару керек:
                  </p>
                  <ul className="ai-insights-list">
                    <li>✏️ Сөйлем құрылымындағы тыныс белгілерді тексеру (Қазақ тілі).</li>
                    <li>📐 Квадрат теңдеулердің түбірлерін есептеу алгоритмін қайталау (Математика).</li>
                    <li>📚 Физика пәнінен формулаларды жаттау.</li>
                  </ul>
                </>
              ) : (
                <p className="ai-insight-text" style={{ color: 'var(--text-secondary)' }}>
                  Ұсыныстар жасау үшін алдымен жұмыстарыңызды тексеруге жіберіңіз.
                </p>
              )}
            </div>
          </Card>
        </div>
      </div>
    </MainLayout>
  );
}

import { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import {
  BookOpen, FileText, Star, CircleAlert, Bot, ArrowLeft, Loader
} from 'lucide-react';
import MainLayout from '../../components/layout/MainLayout';
import Badge from '../../components/ui/Badge';
import CircularProgress from '../../components/ui/CircularProgress';
import { db } from '../../lib/firebase';
import { doc, collection, query, where, onSnapshot } from 'firebase/firestore';
import type { Submission, Review } from '../../types';
import { useAuth } from '../../contexts/AuthContext';
import { STATUS_MAP } from '../../lib/constants';
import './StudentDashboard.css';

export default function StudentDashboard() {
  const { id } = useParams();
  const { user } = useAuth();
  
  const [submission, setSubmission] = useState<Submission | null>(null);
  const [review, setReview] = useState<Review | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!db || !id) return;

    setLoading(true);

    // 1. Listen to submission doc
    const subRef = doc(db, 'submissions', id);
    const unsubscribeSub = onSnapshot(subRef, (docSnap) => {
      if (docSnap.exists()) {
        setSubmission({ id: docSnap.id, ...docSnap.data() } as Submission);
      }
    });

    // 2. Listen to reviews for this submission
    const reviewsQuery = query(collection(db, 'reviews'), where("submissionId", "==", id));
    const unsubscribeReviews = onSnapshot(reviewsQuery, (querySnapshot) => {
      if (!querySnapshot.empty) {
        const docSnap = querySnapshot.docs[0];
        setReview({ id: docSnap.id, ...docSnap.data() } as Review);
      } else {
        setReview(null);
      }
      setLoading(false);
    }, (error) => {
      console.error("Failed to sync review data", error);
      setLoading(false);
    });

    return () => {
      unsubscribeSub();
      unsubscribeReviews();
    };
  }, [id]);

  if (loading) {
    return (
      <MainLayout breadcrumbs={[{ label: 'Жүктелуде...' }]}>
        <div style={{ display: 'flex', justifyContent: 'center', padding: 'var(--space-8)' }}>
          <Loader className="spin" size={32} />
        </div>
      </MainLayout>
    );
  }

  if (!submission) {
    return (
      <MainLayout breadcrumbs={[{ label: 'Қате' }]}>
        <div style={{ padding: 'var(--space-8)', textAlign: 'center' }}>
          <h2>Тапсырма табылмады</h2>
          <Link to="/assignments" style={{ color: 'var(--accent-primary)', textDecoration: 'underline' }}>Тізімге қайту</Link>
        </div>
      </MainLayout>
    );
  }

  const isParent = user?.role === 'parent';
  const backPath = isParent ? '/parent' : '/assignments';
  const backLabel = isParent ? 'Ата-ана кабинеті' : 'Менің тапсырмаларым';

  return (
    <MainLayout
      breadcrumbs={[
        { label: backLabel, path: backPath },
        { label: submission.title },
      ]}
    >
      <Link to={backPath} style={{ display: 'inline-flex', alignItems: 'center', gap: '8px', color: 'var(--text-secondary)', textDecoration: 'none', marginBottom: '16px', fontSize: '0.875rem' }}>
        <ArrowLeft size={16} /> Тізімге қайту
      </Link>

      {/* Page Title */}
      <div className="page-title-section">
        <h1 className="page-title">
          Тапсырма: {submission.title}
          <Badge color="blue">
            <BookOpen size={12} /> {submission.subject}
          </Badge>
        </h1>
        <div className="page-meta">
          <span className="page-meta-item">
            Жүкетелген күні: {new Date((submission.createdAt as any)?.toDate?.() || Date.now()).toLocaleDateString('kk-KZ')}
          </span>
          <span className="page-meta-item">
            Статус: {STATUS_MAP[submission.status]?.label || submission.status}
          </span>
        </div>
      </div>

      <div className="dashboard-grid">
        {/* Left Column */}
        <div className="dashboard-main">
          
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">Сіздің жүктеген файлыңыз</h2>
            </div>
            <div className="card-body">
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <div style={{ padding: '12px', background: 'var(--bg-secondary)', borderRadius: '8px' }}>
                  <FileText size={24} style={{ color: 'var(--accent-primary)' }} />
                </div>
                <div>
                  <div style={{ fontWeight: 500, color: 'var(--text-primary)' }}>{submission.fileName}</div>
                  <a href={submission.fileUrl} target="_blank" rel="noreferrer" style={{ fontSize: '0.8125rem', color: 'var(--accent-primary)', textDecoration: 'underline' }}>Ашу / Көру</a>
                </div>
              </div>
            </div>
          </div>

          {/* Pending Teacher Review State */}
          {submission.status === 'pending_teacher_review' && (
            <div className="card" style={{ marginTop: '24px', textAlign: 'center', padding: '40px 20px', border: '2px dashed var(--color-warning)' }}>
              <div style={{ background: 'var(--bg-secondary)', width: '64px', height: '64px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 16px' }}>
                <Bot size={32} style={{ color: 'var(--color-warning)' }} />
              </div>
              <h3 style={{ marginBottom: '8px' }}>AI талдауы аяқталды, мұғалім тексеруінде</h3>
              <p style={{ color: 'var(--text-secondary)' }}>Жасанды интеллект жұмысыңызды тексерді. Қазір мұғалім нәтижені растап жатыр. Күте тұрыңыз!</p>
            </div>
          )}

          {/* AI Analysis View (Only if reviewed) */}
          {submission.status === 'reviewed' && review ? (
            <div className="card" style={{ marginTop: '24px' }}>
              <div className="card-header" style={{ display: 'flex', alignItems: 'center', gap: '8px', borderBottom: '1px solid var(--border-color)', paddingBottom: '16px', marginBottom: '16px' }}>
                <Bot size={24} style={{ color: 'var(--accent-primary)' }} />
                <h2 className="card-title" style={{ margin: 0 }}>AI Көмекшінің Талдауы және Мұғалім пікірі</h2>
              </div>
              
              <div className="card-body">
                {submission.teacherComment && (
                  <div style={{ marginBottom: '24px', padding: '16px', background: 'var(--accent-primary-light)', borderRadius: '8px', borderLeft: '4px solid var(--accent-primary)' }}>
                    <h3 style={{ fontSize: '1rem', fontWeight: 600, marginBottom: '8px', color: 'var(--accent-primary)' }}>Мұғалім пікірі:</h3>
                    <p style={{ fontSize: '0.9375rem', lineHeight: 1.6, color: 'var(--text-primary)' }}>
                      {submission.teacherComment}
                    </p>
                  </div>
                )}

                <div style={{ marginBottom: '24px' }}>
                  <h3 style={{ fontSize: '1rem', fontWeight: 600, marginBottom: '8px' }}>AI пікірі:</h3>
                  <p style={{ fontSize: '0.9375rem', lineHeight: 1.6, color: 'var(--text-secondary)' }}>
                    {review.feedback}
                  </p>
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px' }}>
                  {/* Mistakes */}
                  <div>
                    <h3 style={{ fontSize: '0.9375rem', fontWeight: 600, marginBottom: '12px', color: 'var(--color-error)', display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <CircleAlert size={16} /> Қателер ({review.mistakes?.length || 0})
                    </h3>
                    <ul style={{ listStyle: 'none', padding: 0, margin: 0, display: 'flex', flexDirection: 'column', gap: '8px' }}>
                      {review.mistakes?.map((m, i) => (
                        <li key={i} style={{ fontSize: '0.875rem', padding: '8px 12px', background: 'var(--bg-secondary)', borderRadius: '6px', borderLeft: '3px solid var(--color-error)' }}>
                          <strong>{m.type}:</strong> {m.description}
                        </li>
                      ))}
                      {(!review.mistakes || review.mistakes.length === 0) && (
                        <li style={{ fontSize: '0.875rem', color: 'var(--text-tertiary)' }}>Қателер табылмады!</li>
                      )}
                    </ul>
                  </div>

                  {/* Recommendations */}
                  <div>
                    <h3 style={{ fontSize: '0.9375rem', fontWeight: 600, marginBottom: '12px', color: 'var(--color-warning)', display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <Star size={16} /> Ұсыныстар
                    </h3>
                    <ul style={{ listStyle: 'none', padding: 0, margin: 0, display: 'flex', flexDirection: 'column', gap: '8px' }}>
                      {review.recommendations?.map((r, i) => (
                        <li key={i} style={{ fontSize: '0.875rem', padding: '8px 12px', background: 'var(--bg-secondary)', borderRadius: '6px', borderLeft: '3px solid var(--color-warning)' }}>
                          {r}
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              </div>
            </div>
          ) : submission.status !== 'pending_teacher_review' && (
            <div className="card" style={{ marginTop: '24px', textAlign: 'center', padding: '40px 20px' }}>
              <Loader size={32} className="spin" style={{ margin: '0 auto 16px', color: 'var(--accent-primary)' }} />
              <h3 style={{ marginBottom: '8px' }}>Жұмыс тексерілуде...</h3>
              <p style={{ color: 'var(--text-secondary)' }}>Мұғалім немесе AI жұмысыңызды тексерген соң, нәтиже осында пайда болады.</p>
            </div>
          )}

        </div>

        {/* Right Sidebar (Score) */}
        <div className="dashboard-sidebar">
          {submission.status === 'reviewed' ? (
            <div className="card score-card">
              <h2 className="score-title">Қорытынды баға</h2>
              <div className="score-circle-wrapper">
                <CircularProgress 
                  value={submission.score || 0} 
                  size={140} 
                  strokeWidth={12} 
                />
                <div className="score-text-overlay">
                  <span className="score-main-value">{submission.score || 0}</span>
                  <span className="score-max-value">/ {review?.maxScore || 100}</span>
                </div>
              </div>
              <p className="score-verdict">
                {(submission.score || 0) >= 85 ? 'Жарайсың! Өте жақсы жұмыс.' : (submission.score || 0) >= 60 ? 'Жақсы, бірақ қателермен жұмыс істеу керек.' : 'Тақырыпты қайталап оқу керек.'}
              </p>
            </div>
          ) : (
            <div className="card score-card">
              <h2 className="score-title">Сіздің бағаңыз</h2>
              <div className="score-circle-wrapper">
                <CircularProgress value={0} size={140} strokeWidth={12} />
                <div className="score-text-overlay">
                  <span className="score-main-value">-</span>
                </div>
              </div>
              <p className="score-verdict" style={{ color: 'var(--text-secondary)' }}>Әлі бағаланбаған</p>
            </div>
          )}
        </div>
      </div>
    </MainLayout>
  );
}

import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { BookOpen, FileText, Plus, KeyRound, Award, Loader } from 'lucide-react';
import MainLayout from '../../components/layout/MainLayout';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import Badge from '../../components/ui/Badge';
import { useAuth } from '../../contexts/AuthContext';
import { db } from '../../lib/firebase';
import { collection, query, where, onSnapshot, doc, getDoc, updateDoc } from 'firebase/firestore';
import type { Submission } from '../../types';
import './StudentHome.css';

interface SchoolClass {
  id: string;
  name: string;
  teacherId: string;
  inviteCode?: string;
  studentsCount?: number;
}

export default function StudentHome() {
  const { user } = useAuth();
  const [classes, setClasses] = useState<SchoolClass[]>([]);
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(true);

  const [studentDocIds, setStudentDocIds] = useState<string[]>([]);

  // Generate parent code for existing students if missing
  useEffect(() => {
    if (!db || !user || user.role !== 'student') return;
    if (!user.parentCode) {
      const generateAndSave = async () => {
        const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
        let code = '';
        for (let i = 0; i < 6; i++) {
          code += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        try {
          await updateDoc(doc(db, 'users', user.id), { parentCode: code });
          // Note: The UI will update when the user refreshes or auth state syncs, 
          // or we can just rely on the next login. Since this is an edge case 
          // for old users, it's fine if they need to refresh.
        } catch (err) {
          console.error("Failed to generate parent code", err);
        }
      };
      generateAndSave();
    }
  }, [user]);

  useEffect(() => {
    if (!db || !user) return;

    setLoading(true);

    // 1. Listen to student's memberships in classes
    const studentQuery = query(
      collection(db, 'students'), 
      where("email", "==", user.email)
    );

    const unsubscribeStudents = onSnapshot(studentQuery, async (querySnapshot) => {
      const classIds: string[] = [];
      const docIds = [user.id];
      querySnapshot.forEach((docSnap) => {
        docIds.push(docSnap.id);
        const data = docSnap.data();
        if (data.classId && !classIds.includes(data.classId)) {
          classIds.push(data.classId);
        }
      });
      setStudentDocIds(Array.from(new Set(docIds)));

      if (classIds.length === 0) {
        setClasses([]);
        setLoading(false);
        return;
      }

      // Fetch class details
      const classesData: SchoolClass[] = [];
      for (const cid of classIds) {
        try {
          const classDoc = await getDoc(doc(db, 'classes', cid));
          if (classDoc.exists()) {
            classesData.push({ id: classDoc.id, ...classDoc.data() } as SchoolClass);
          }
        } catch (err) {
          console.error("Error fetching class details:", err);
        }
      }
      setClasses(classesData);
      setLoading(false);
    }, (error) => {
      console.error("Failed to sync student classes:", error);
      setLoading(false);
    });

    return () => unsubscribeStudents();
  }, [user]);

  // 2. Listen to student's submissions once studentDocIds are resolved
  useEffect(() => {
    if (!db || !user || studentDocIds.length === 0) return;

    const subQuery = query(
      collection(db, 'submissions'),
      where("studentId", "in", studentDocIds)
    );

    const unsubscribeSubmissions = onSnapshot(subQuery, (querySnapshot) => {
      const subs: Submission[] = [];
      querySnapshot.forEach((docSnap) => {
        subs.push({ id: docSnap.id, ...docSnap.data() } as Submission);
      });
      // Sort newest first
      subs.sort((a, b) => {
        const timeA = (a.createdAt as any)?.seconds || 0;
        const timeB = (b.createdAt as any)?.seconds || 0;
        return timeB - timeA;
      });
      setSubmissions(subs);
    });

    return () => unsubscribeSubmissions();
  }, [studentDocIds, user]);

  // Calculations
  const reviewedSubmissions = submissions.filter(s => s.status === 'reviewed');
  const totalScore = reviewedSubmissions.reduce((sum, s) => {
    return sum + (s.score || 85);
  }, 0);
  const averageScore = reviewedSubmissions.length > 0 ? Math.round(totalScore / reviewedSubmissions.length) : 0;

  return (
    <MainLayout breadcrumbs={[{ label: 'Басты бет' }]}>
      {/* Welcome Header */}
      <div className="student-home-welcome">
        <div>
          <h1 className="welcome-title">Сәлем, {user?.name}! 👋</h1>
          <p className="welcome-subtitle">NÄTIJE AI білім беру жүйесіне қош келдіңіз. Бүгінгі үлгеріміңізді тексеріңіз.</p>
        </div>
        <div style={{ display: 'flex', gap: '12px', alignItems: 'center', flexWrap: 'wrap' }}>
          <div style={{ padding: '8px 16px', background: 'var(--bg-secondary)', borderRadius: '8px', border: '1px solid var(--border-color)', display: 'flex', alignItems: 'center', gap: '8px' }}>
            <KeyRound size={16} style={{ color: 'var(--accent-primary)' }} />
            <span style={{ fontSize: '0.875rem', color: 'var(--text-secondary)' }}>Ата-анаға арналған код:</span>
            <strong style={{ fontSize: '1rem', letterSpacing: '1px', userSelect: 'all' }}>{user?.parentCode || '...'}</strong>
          </div>
          <Link to="/join-class" style={{ textDecoration: 'none' }}>
            <Button variant="primary" icon={<Plus size={16} />}>
              Сыныпқа қосылу
            </Button>
          </Link>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="student-home-stats">
        <Card className="stat-card">
          <div className="stat-icon-wrapper" style={{ background: 'var(--accent-primary-light)', color: 'var(--accent-primary)' }}>
            <BookOpen size={22} />
          </div>
          <div className="stat-info">
            <span className="stat-label">Қосылған сыныптар</span>
            <span className="stat-value">{classes.length}</span>
          </div>
        </Card>

        <Card className="stat-card">
          <div className="stat-icon-wrapper" style={{ background: 'rgba(59, 130, 246, 0.1)', color: '#3b82f6' }}>
            <FileText size={22} />
          </div>
          <div className="stat-info">
            <span className="stat-label">Жүктелген жұмыстар</span>
            <span className="stat-value">{submissions.length}</span>
          </div>
        </Card>

        <Card className="stat-card">
          <div className="stat-icon-wrapper" style={{ background: 'var(--color-success-light)', color: 'var(--color-success)' }}>
            <Award size={22} />
          </div>
          <div className="stat-info">
            <span className="stat-label">Орташа балл</span>
            <span className="stat-value">{averageScore > 0 ? `${averageScore}%` : '—'}</span>
          </div>
        </Card>
      </div>

      {/* Main Grid: Classes & Submissions */}
      <div className="student-home-grid">
        {/* Left Column: Classes */}
        <div className="grid-left">
          <div className="section-header-row">
            <h2 className="section-title">Менің сыныптарым ({classes.length})</h2>
          </div>

          {loading ? (
            <div className="loading-container">
              <Loader className="spin" size={24} />
            </div>
          ) : classes.length > 0 ? (
            <div className="classes-list-grid">
              {classes.map((c) => (
                <Card key={c.id} variant="hover" className="class-card">
                  <div className="class-card-header">
                    <div className="class-avatar">
                      {c.name.substring(0, 2)}
                    </div>
                    <div>
                      <h3 className="class-name">{c.name} сыныбы</h3>
                      <div className="class-code-badge">
                        <KeyRound size={12} />
                        <span>Код: {c.inviteCode}</span>
                      </div>
                    </div>
                  </div>
                  <div className="class-card-footer">
                    <span className="student-count">Оқушылар саны: {c.studentsCount || 1}</span>
                    <Badge color="green" filled>Белсенді</Badge>
                  </div>
                </Card>
              ))}
            </div>
          ) : (
            <Card className="empty-classes-card">
              <BookOpen size={48} className="empty-icon" />
              <h3>Сыныптарға әлі қосылмағансыз</h3>
              <p>Үй жұмыстарын жіберу және баға алу үшін мұғалімнен алған код арқылы сыныпқа қосылыңыз.</p>
              <Link to="/join-class" style={{ textDecoration: 'none', marginTop: '16px', display: 'inline-block' }}>
                <Button variant="outline" size="sm" icon={<Plus size={14} />}>Сыныпқа қосылу</Button>
              </Link>
            </Card>
          )}
        </div>

        {/* Right Column: Recent Activity / Submissions */}
        <div className="grid-right">
          <div className="section-header-row">
            <h2 className="section-title">Соңғы жұмыстар</h2>
            {submissions.length > 3 && (
              <Link to="/assignments" className="view-all-link">Барлығын көру</Link>
            )}
          </div>

          <Card className="recent-submissions-card">
            {submissions.length > 0 ? (
              <div className="recent-submissions-list">
                {submissions.slice(0, 4).map((sub) => (
                  <Link key={sub.id} to={`/assignments/${sub.id}`} className="submission-item-link">
                    <div className="submission-item-row">
                      <div className="submission-info-group">
                        <div className="submission-file-icon">
                          <FileText size={18} />
                        </div>
                        <div>
                          <h4 className="submission-title">{sub.title}</h4>
                          <span className="submission-subject">{sub.subject}</span>
                        </div>
                      </div>
                      <div className="submission-status-group">
                        {sub.status === 'reviewed' ? (
                          <span className="score-badge">{sub.score || 85}/100</span>
                        ) : (
                          <Badge color="yellow">Тексерілуде</Badge>
                        )}
                      </div>
                    </div>
                  </Link>
                ))}
              </div>
            ) : (
              <div className="empty-submissions">
                <FileText size={36} className="empty-icon" />
                <p>Жүктелген жұмыстар жоқ</p>
              </div>
            )}
          </Card>
        </div>
      </div>
    </MainLayout>
  );
}

